package qwen3tts

import (
	"encoding/binary"
	"math"
	"os"
	"path/filepath"
	"testing"
)

// The fixture was generated by scripts/qwen3tts_probe_erff.rs using
// libm=0.2.16. Each eight-byte record stores input and expected F32 bits.
func TestDecoderErffPinnedLibm(t *testing.T) {
	if err := verifyReleasedFile(filepath.Join("..", "..", "scripts", "qwen3tts_probe_erff.rs"), "bda53965524be20c8c2d7699a948f9a7f66760663061a856361b1d2086f51f1b", 0); err != nil {
		t.Fatal(err)
	}
	path := filepath.Join("testdata", "erff_libm_0_2_16.u32le")
	if err := verifyReleasedFile(path, "774c1608e9a0a60e338af4397ba75b38bef18d023c0748740e737a7a02ab2f7c", 75096); err != nil {
		t.Fatal(err)
	}
	data, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	for i := 0; i < len(data); i += 8 {
		in := binary.LittleEndian.Uint32(data[i:])
		want := binary.LittleEndian.Uint32(data[i+4:])
		got := math.Float32bits(decoderErff(math.Float32frombits(in)))
		if in&0x7fffffff > 0x7f800000 {
			if !math.IsNaN(float64(math.Float32frombits(got))) {
				t.Fatalf("case%d NaN input got=%08x", i/8, got)
			}
			continue
		}
		if got != want {
			t.Fatalf("case%d input=%08x got=%08x want=%08x", i/8, in, got, want)
		}
	}
}
